require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['especialista'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$id=(int)($_GET['id']??$_POST['id_reparacion']??0);$q=$pdo->prepare('SELECT r.*,s.id_solicitud,s.marca,s.modelo FROM reparaciones r JOIN solicitudes s ON s.id_solicitud=r.id_solicitud WHERE r.id_reparacion=? AND r.id_especialista=?');$q->execute([$id,$_SESSION['usuario']['id_usuario']]);$reparacion=$q->fetch();if(!$reparacion){establecer_mensaje('error','Reparación no encontrada.');redirigir('mis_reparaciones.php');}$errores=[];if($_SERVER['REQUEST_METHOD']==='POST'){$estado=$_POST['estado']??'';$permitidos=['Pendiente','Diagnóstico','En reparación','En pruebas','Terminada'];$diagnostico=trim($_POST['diagnostico']??'');$trabajo=trim($_POST['trabajo_realizado']??'');$piezas=trim($_POST['piezas_utilizadas']??'');$obs=trim($_POST['observaciones']??'');$comentario=trim($_POST['comentario']??'');if(!in_array($estado,$permitidos,true))$errores[]='Estado no válido.';if($estado==='Terminada'&&$trabajo==='')$errores[]='Registra el trabajo realizado antes de terminar.';if(!$errores){$pdo->beginTransaction();try{$fecha_inicio=$reparacion['fecha_inicio']?:date('Y-m-d H:i:s');$fecha_fin=$estado==='Terminada'?date('Y-m-d H:i:s'):null;$q=$pdo->prepare('UPDATE reparaciones SET estado=?,fecha_inicio=?,fecha_fin=?,diagnostico=?,trabajo_realizado=?,piezas_utilizadas=?,observaciones=? WHERE id_reparacion=? AND id_especialista=?');$q->execute([$estado,$fecha_inicio,$fecha_fin,$diagnostico,$trabajo,$piezas,$obs,$id,$_SESSION['usuario']['id_usuario']]);registrar_historial($pdo,$id,$reparacion['estado'],$estado,$comentario?:'Se actualizó la información de la reparación.',$_SESSION['usuario']['id_usuario']);$estado_solicitud=$estado==='Terminada'?'Terminada':($estado==='Pendiente'?'Aceptada':'En reparación');$q=$pdo->prepare('UPDATE solicitudes SET estado=? WHERE id_solicitud=?');$q->execute([$estado_solicitud,$reparacion['id_solicitud']]);if($estado==='Terminada'){$q=$pdo->prepare('SELECT c.costo_reparacion,c.costo_refacciones,c.costo_total FROM cotizaciones c WHERE c.id_solicitud=?');$q->execute([$reparacion['id_solicitud']]);$cot=$q->fetch();if($cot){$q=$pdo->prepare('INSERT IGNORE INTO facturas (id_solicitud,numero_servicio,subtotal,refacciones,total) VALUES (?,?,?,?,?)');$numero='RF-'.str_pad((string)$reparacion['id_solicitud'],6,'0',STR_PAD_LEFT);$q->execute([$reparacion['id_solicitud'],$numero,$cot['costo_reparacion'],$cot['costo_refacciones'],$cot['costo_total']]);$q=$pdo->prepare('INSERT INTO pagos (id_solicitud,monto,metodo_pago,estado) VALUES (?,?,"Efectivo","Pendiente") ON DUPLICATE KEY UPDATE monto=VALUES(monto)');$q->execute([$reparacion['id_solicitud'],$cot['costo_total']]);}}$pdo->commit();establecer_mensaje('exito','Estado de reparación actualizado.');redirigir('detalle_reparacion.php?id='.$id);}catch(Throwable $e){$pdo->rollBack();$errores[]='No se pudo guardar el avance.';}}}$titulo_pagina='Actualizar reparación';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">REPARACIÓN #<?= $id ?></span><h1>Actualizar proceso</h1><p><?= escapar($reparacion['marca'].' '.$reparacion['modelo']) ?></p></div></div><?php if($errores): ?><div class="alerta alerta-error"><?= escapar(implode(' ',$errores)) ?></div><?php endif; ?><form method="post" class="formulario-panel formulario"><input type="hidden" name="id_reparacion" value="<?= $id ?>"><label>Estado<select name="estado" required><?php foreach(['Pendiente','Diagnóstico','En reparación','En pruebas','Terminada'] as $estado): ?><option <?= $reparacion['estado']===$estado?'selected':'' ?>><?= $estado ?></option><?php endforeach; ?></select></label><label>Diagnóstico<textarea name="diagnostico"><?= escapar($reparacion['diagnostico']) ?></textarea></label><label>Trabajo realizado<textarea name="trabajo_realizado"><?= escapar($reparacion['trabajo_realizado']) ?></textarea></label><label>Piezas utilizadas<textarea name="piezas_utilizadas"><?= escapar($reparacion['piezas_utilizadas']) ?></textarea></label><label>Observaciones<textarea name="observaciones"><?= escapar($reparacion['observaciones']) ?></textarea></label><label>Comentario del cambio<input name="comentario" placeholder="Se reemplazó el capacitor..." required></label><div class="acciones"><button class="boton" type="submit">Guardar avance →</button><a class="boton boton-secundario" href="detalle_reparacion.php?id=<?= $id ?>">Cancelar</a></div></form><?php require_once __DIR__.'/../includes/pie.php'; ?>


